//! Blocks of hand-written site pages that bindgen fills, each between a
//! `<!-- Generated by bitview_bindgen: NAME -->` line and an `<!-- End of bitview_bindgen: NAME -->`
//! line.

use std::{fs, io, path::Path};

use crate::generators::{reading_rules, write_if_changed};

/// A named block and its content, rendered at the start marker's indentation.
struct Block {
    name: &'static str,
    render: fn(&str) -> String,
}

const BLOCKS: &[Block] = &[Block {
    name: "reading-rules",
    render: reading_rules::html,
}];

impl Block {
    fn start(&self) -> String {
        format!("<!-- Generated by bitview_bindgen: {} -->", self.name)
    }

    fn end(&self) -> String {
        format!("<!-- End of bitview_bindgen: {} -->", self.name)
    }
}

/// Fills every block each page holds; a page that holds none fails, as a listed page by mistake.
pub fn fill_site_pages<P: AsRef<Path>>(pages: &[P]) -> io::Result<()> {
    for path in pages {
        let path = path.as_ref();
        let invalid = |what: String| io::Error::new(io::ErrorKind::InvalidData, format!("{}: {what}", path.display()));
        let mut page = fs::read_to_string(path)?;
        let held = BLOCKS.iter().filter(|block| page.contains(&block.start())).collect::<Vec<_>>();
        if held.is_empty() {
            return Err(invalid("no bitview_bindgen block".to_owned()));
        }
        for block in held {
            page = replace_block(&page, block).map_err(invalid)?;
        }
        write_if_changed(path, &page)?;
    }
    Ok(())
}

/// The page with `block`'s content between its markers, which must each stand alone on their
/// line and appear once. The page's line endings are kept.
fn replace_block(page: &str, block: &Block) -> Result<String, String> {
    let (start, end) = (block.start(), block.end());
    let newline = if page.contains("\r\n") { "\r\n" } else { "\n" };
    let (before, rest) = page.split_once(&start).ok_or_else(|| format!("no {start}"))?;
    let (old, after) = rest.split_once(&end).ok_or_else(|| format!("no {end} after {start}"))?;
    if old.contains(&start) || after.contains(&start) || after.contains(&end) {
        return Err(format!("a second {start} block"));
    }
    let indent = before.rsplit_once('\n').map_or(before, |(_, line)| line);
    let (start_rest, old) = old.split_once('\n').ok_or_else(|| format!("{end} on {start}'s line"))?;
    let end_indent = old.rsplit_once('\n').map_or(old, |(_, line)| line);
    if !indent.trim().is_empty() || !start_rest.trim().is_empty() {
        return Err(format!("text beside {start} on its line"));
    }
    if !end_indent.trim().is_empty() {
        return Err(format!("text before {end} on its line"));
    }
    let content = (block.render)(indent).replace('\n', newline);
    Ok(format!("{before}{start}{newline}{content}{end_indent}{end}{after}"))
}
